tools.example:
ch = sfroot().find('-isa', 'Stateflow.Chart', 'Path', 'myModel/Chart');
s = Stateflow.State(ch);
s.Name = 'Heating';
s.LabelString = sprintf('Heating\nentry: heater = true;\nexit: heater = false;');
s.Position = [40 40 140 80];

tools.usage:
StateName
en: action;
du: action;
ex: action;
on E: action;
en, du: action;   % combined

tools.example:
Running
en: count = 0;
du: count = count + 1;
on every(10, tick): log = count;
ex: done = true;

t = Stateflow.Transition(ch);
t.Source = sOff; t.Destination = sOn;
t.LabelString = '[temp < setpoint - 1]{requests = requests + 1;}';

t = Stateflow.Transition(ch);
t.Destination = sOff;
t.DestinationOClock = 0;
t.SourceEndpoint = t.DestinationEndpoint - [0 30];
t.MidPoint = t.DestinationEndpoint - [0 15];

j = Stateflow.Junction(ch);
j.Position.Center = [200 120];
t1 = Stateflow.Transition(ch); t1.Source = sIdle; t1.Destination = j; t1.LabelString = '[go]';
t2 = Stateflow.Transition(ch); t2.Source = j; t2.Destination = sFast; t2.LabelString = '[mode == 1]';
t3 = Stateflow.Transition(ch); t3.Source = j; t3.Destination = sSlow;

h = Stateflow.Junction(sRunning);
h.Type = 'HISTORY';
h.Position.Center = sRunning.Position(1:2) + [15 25];

f = Stateflow.Function(ch);
f.LabelString = 'y = clampVal(u, lo, hi)';
f.Position = [300 30 150 90];
% then draw junction/transition flow inside f

b = Stateflow.Box(ch);
b.Name = 'Utilities';
b.Position = [20 300 250 120];

% Link a library chart as an atomic subchart
lib = sfroot().find('-isa', 'Stateflow.Chart', 'Path', 'myLib/Debounce');
as = Stateflow.AtomicSubchart(ch);
as.Name = 'Debounce1';

ch.HasOutputData = true;
ch.OutputMonitoringMode = 'ChildActivity';
ch.OutputData.Name = 'mode';   % enumerated output listing the top-level states

d = Stateflow.Data(ch);
d.Name = 'temp'; d.Scope = 'Input'; d.DataType = 'single';
y = Stateflow.Data(ch);
y.Name = 'heater'; y.Scope = 'Output'; y.DataType = 'boolean';
y.Props.InitialValue = 'false';

e = Stateflow.Event(ch);
e.Name = 'tick1ms'; e.Scope = 'Input'; e.Trigger = 'Function call';
% in an action: send(stopEvt) broadcasts a local event

m = Stateflow.Message(ch);
m.Name = 'cmd'; m.Scope = 'Input';
% transition label consuming the message:  cmd[cmd.data == 1]

j = Stateflow.Junction(ch);
j.Position.Center = [150 200];
j.Position.Radius = 7;

f = Stateflow.Function(ch);
f.LabelString = 'y = sat(u)';
f.Position = [300 40 120 80];

b = Stateflow.Box(ch);
b.Name = 'Diagnostics';
b.Position = [10 250 300 150];

as = Stateflow.AtomicSubchart(ch);
as.Name = 'Debouncer';
sub = as.Subchart;
s = Stateflow.State(sub); s.Name = 'Idle';

tt = Stateflow.TruthTable(ch);
tt.LabelString = 'y = sel(a, b)';
tt.ConditionTable = {'a high', 'a > 0', 'T', 'F'; 'b high', 'b > 0', '-', '-'; '', 'Actions', '1', '2'};
tt.ActionTable = {'', 'y = 1;'; '', 'y = 0;'};

f = Stateflow.EMFunction(ch);
f.LabelString = 'y = rms3(u)';
f.Script = sprintf('function y = rms3(u)\ny = sqrt(mean(u.^2));');

f = Stateflow.SLFunction(ch);
f.LabelString = 'y = lowpass(u)';
f.Position = [320 180 140 70];
% edit the Simulink contents by opening the function box

